/// 计划构建的 RAII 包装, 保证用例失败时也释放.
class Plan {
  public:
    Plan() : plan_(webgal_plan_create()) {
        REQUIRE(plan_ != nullptr);
    }
    ~Plan() {
        webgal_plan_destroy(plan_);
    }

    Plan(const Plan&) = delete;
    Plan& operator=(const Plan&) = delete;

    [[nodiscard]] WebgalPlan* get() const {
        return plan_;
    }

  private:
    WebgalPlan* plan_ = nullptr;
};

void set_minimal_meta(WebgalPlan* plan, std::uint64_t duration_us) {
    REQUIRE(webgal_plan_set_meta(plan, "C:/project", 1920, 1080, 1280, 720, 30, 1, duration_us, 1,
                                 1.0F, 0) == WEBGAL_STATUS_OK);
}

/// 写一个 48kHz stereo 的短 WAV，用来验证分块混音真的把样本写进了输出。
void write_test_wav(const std::filesystem::path& path, std::uint32_t frames) {
    constexpr std::uint32_t kChannels = 2;
    const std::uint32_t data_bytes = frames * kChannels * 2;
    std::ofstream output(path, std::ios::binary | std::ios::trunc);
    REQUIRE(output);
    output.write("RIFF", 4);
    const std::uint32_t riff_size = 36 + data_bytes;
    output.write(reinterpret_cast<const char*>(&riff_size), 4);
    output.write("WAVEfmt ", 8);
    const std::uint32_t fmt_size = 16;
    const std::uint16_t format = 1;
    const std::uint16_t channels = kChannels;
    const std::uint32_t sample_rate = 48000;
    const std::uint32_t byte_rate = sample_rate * kChannels * 2;
    const std::uint16_t block_align = kChannels * 2;
    const std::uint16_t bits = 16;
    output.write(reinterpret_cast<const char*>(&fmt_size), 4);
    output.write(reinterpret_cast<const char*>(&format), 2);
    output.write(reinterpret_cast<const char*>(&channels), 2);
    output.write(reinterpret_cast<const char*>(&sample_rate), 4);
    output.write(reinterpret_cast<const char*>(&byte_rate), 4);
    output.write(reinterpret_cast<const char*>(&block_align), 2);
    output.write(reinterpret_cast<const char*>(&bits), 2);
    output.write("data", 4);
    output.write(reinterpret_cast<const char*>(&data_bytes), 4);
    for (std::uint32_t frame = 0; frame < frames; ++frame) {
        const float phase =
            static_cast<float>(frame) / 48000.0F * 440.0F * 2.0F * std::numbers::pi_v<float>;
        const auto sample = static_cast<std::int16_t>(std::sin(phase) * 12000.0F);
        for (std::uint32_t channel = 0; channel < kChannels; ++channel) {
            output.write(reinterpret_cast<const char*>(&sample), 2);
        }
    }
}

